import { useState } from 'react';
import { JxCalendar, JxChip } from '@jinx-ui/react';

interface ReportDatePickerProps {
  onChange?: (date: Date) => void;
}

function startOfDay(date: Date): Date {
  const copy = new Date(date);
  copy.setHours(0, 0, 0, 0);
  return copy;
}

function addDays(date: Date, days: number): Date {
  const copy = new Date(date);
  copy.setDate(copy.getDate() + days);
  return copy;
}

function isSameDay(a: Date | null, b: Date): boolean {
  if (!a) return false;
  return (
    a.getFullYear() === b.getFullYear() &&
    a.getMonth() === b.getMonth() &&
    a.getDate() === b.getDate()
  );
}

export default function ReportDatePicker({ onChange }: ReportDatePickerProps) {
  const [date, setDate] = useState<Date | null>(startOfDay(new Date()));

  const quickOptions = [
    { label: 'Сегодня', getValue: () => startOfDay(new Date()) },
    { label: 'Вчера', getValue: () => addDays(startOfDay(new Date()), -1) },
    { label: 'Неделя назад', getValue: () => addDays(startOfDay(new Date()), -7) },
  ];

  const applyDate = (next: Date) => {
    setDate(next);
    onChange?.(next);
  };

  const handleCalendarChange = (value: Date | null) => {
    if (value) {
      applyDate(startOfDay(value));
    } else {
      setDate(null);
    }
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-r-sm)' }}>
      <div
        role="group"
        aria-label="Быстрый выбор даты"
        style={{ display: 'flex', gap: 'var(--jx-r-xs)', flexWrap: 'wrap' }}
      >
        {quickOptions.map((option) => {
          const optionValue = option.getValue();
          return (
            <JxChip
              key={option.label}
              active={isSameDay(date, optionValue)}
              onClick={() => applyDate(optionValue)}
            >
              {option.label}
            </JxChip>
          );
        })}
      </div>
      <JxCalendar locale="ru-RU" value={date} onValueChange={handleCalendarChange} />
    </div>
  );
}

